// Beallitasok es a letoltendo szezonok.
//
// A szezonkod YYZZ: a 2026/27-es szezon '2627'. Ket szezont toltunk be,
// mert a folyo szezon elejen meg alig van meccs (a modell kulonben
// 3 meccsbol probalna csapaterosseget becsulni).

const NOW = new Date();
const y = NOW.getUTCFullYear(), mo = NOW.getUTCMonth() + 1;
// a szezon augusztusban indul: januar-julius kozott meg az elozo evi szezonban vagyunk
const startYear = mo >= 8 ? y : y - 1;
const sc = yr => String(yr % 100).padStart(2, '0') + String((yr + 1) % 100).padStart(2, '0');
const SEASONS = [sc(startYear), sc(startYear - 1)];

const LEAGUES = [
  { code: 'E0',  api: 'soccer_epl',                 name: 'Premier League' },
  { code: 'SP1', api: 'soccer_spain_la_liga',       name: 'La Liga' },
  { code: 'D1',  api: 'soccer_germany_bundesliga',  name: 'Bundesliga' },
  { code: 'I1',  api: 'soccer_italy_serie_a',       name: 'Serie A' },
  { code: 'F1',  api: 'soccer_france_ligue_one',    name: 'Ligue 1' },
];

const CONFIG = {
  minOdds: 1.30,        // ez alatt nem erdekel a kimenetel
  maxOdds: 8.0,
  maxHoursAhead: 72,    // ennyi oran belul kezdodo meccsek
  myBook: 'bet365',     // a te alapertelmezett konyved (ar-osszehasonlitashoz)
  minGapPct: 2.0,       // ekkora arkulonbsegtol jelzi kulon
  maxTips: 15,          // max ennyi meccs az uzenetben
};

const out = [];
for (const lg of LEAGUES) {
  for (const s of SEASONS) {
    out.push({ json: {
      url: `https://www.football-data.co.uk/mmz4281/${s}/${lg.code}.csv`,
      league: lg.code, api: lg.api, league_name: lg.name, season: s,
      leagues: LEAGUES, config: CONFIG,
    }});
  }
}
return out;

// CSV feldolgozas + Dixon-Coles csapaterossegek.
// Ez a kod lokalisan tesztelve lett 1849 meccsen mielott ide kerult.

const XI = 0.0065;      // idobeli sulyozas: ~107 napos felezes
const SHRINK_K = 12;    // ennyi sulyozott meccsnel 50% a sajat adat
const XG_BLEND = 0.5;   // xG es valos gol keverese
const PRIOR_ATT = 0.92; // ujoncok atlag alatt teljesitenek
const PRIOR_DEF = 1.08;

function parseCsv(raw, league) {
  const text = String(raw).replace(/^\uFEFF/, '');
  const lines = text.split(/\r?\n/).filter(l => l.trim().length > 0);
  if (lines.length < 2) return [];
  // fejlecnev szerinti indexeles: az oszlopsorrend szezononkent valtozik
  const head = lines[0].split(',').map(h => h.trim());
  const col = {};
  head.forEach((h, i) => { if (col[h] === undefined) col[h] = i; });
  for (const n of ['Date', 'HomeTeam', 'AwayTeam', 'FTHG', 'FTAG']) {
    if (col[n] === undefined) return [];
  }
  const hasXg = col['HxG'] !== undefined && col['AxG'] !== undefined;
  const out = [];
  for (let i = 1; i < lines.length; i++) {
    const f = lines[i].split(',');
    const home = (f[col['HomeTeam']] || '').trim();
    const away = (f[col['AwayTeam']] || '').trim();
    const fthg = f[col['FTHG']], ftag = f[col['FTAG']];
    if (!home || !away || fthg === undefined || fthg === '' || ftag === '') continue;
    const hg = Number(fthg), ag = Number(ftag);
    if (!Number.isFinite(hg) || !Number.isFinite(ag)) continue;
    // dd/mm/yyyy — NEM ISO, kezzel kell bontani
    const m = (f[col['Date']] || '').trim().match(/^(\d{2})\/(\d{2})\/(\d{2}|\d{4})$/);
    if (!m) continue;
    const yr = m[3].length === 2 ? 2000 + Number(m[3]) : Number(m[3]);
    const date = new Date(Date.UTC(yr, Number(m[2]) - 1, Number(m[1])));
    if (isNaN(date.getTime())) continue;
    const row = { league, date: date.toISOString(), home, away, hg, ag, hxg: null, axg: null };
    if (hasXg) {
      const hx = Number(f[col['HxG']]), ax = Number(f[col['AxG']]);
      if (Number.isFinite(hx) && Number.isFinite(ax)) { row.hxg = hx; row.axg = ax; }
    }
    out.push(row);
  }
  return out;
}

// --- osszes CSV beolvasasa ---
let matches = [];
const fetchErrors = [];
let config = null, leagues = null;

for (const item of $input.all()) {
  const j = item.json;
  if (!config && j.config) { config = j.config; leagues = j.leagues; }
  const status = j.statusCode;
  const body = j.body !== undefined ? j.body : j.data;
  if (status && status !== 200) {
    fetchErrors.push(`${j.league || '?'} ${j.season || ''}: HTTP ${status}`);
    continue;
  }
  if (typeof body !== 'string' || body.length < 100) {
    fetchErrors.push(`${j.league || '?'} ${j.season || ''}: ures valasz`);
    continue;
  }
  const rows = parseCsv(body, j.league);
  if (!rows.length) fetchErrors.push(`${j.league} ${j.season}: 0 meccs`);
  matches = matches.concat(rows);
}

if (!config) { config = {}; leagues = []; }

// --- Dixon-Coles erossegek ---
const now = new Date();
const byLeague = {};
for (const m of matches) (byLeague[m.league] = byLeague[m.league] || []).push(m);

const ratings = {};
const leagueMeta = {};

for (const [league, rows] of Object.entries(byLeague)) {
  const enriched = rows.map(m => {
    const days = Math.max(0, (now - new Date(m.date)) / 86400000);
    const w = Math.exp(-XI * days);
    let hVal = m.hg, aVal = m.ag;
    if (m.hxg !== null && m.axg !== null) {
      hVal = XG_BLEND * m.hxg + (1 - XG_BLEND) * m.hg;
      aVal = XG_BLEND * m.axg + (1 - XG_BLEND) * m.ag;
    }
    return { ...m, w, hVal, aVal };
  }).filter(m => m.w > 1e-6);
  if (!enriched.length) continue;

  let sw = 0, shg = 0, sag = 0;
  for (const m of enriched) { sw += m.w; shg += m.w * m.hVal; sag += m.w * m.aVal; }
  const avgHome = shg / sw, avgAway = sag / sw;
  const leagueAvg = (avgHome + avgAway) / 2;
  const homeAdv = avgAway > 0 ? avgHome / avgAway : 1.3;
  leagueMeta[league] = { leagueAvg, homeAdv, matches: enriched.length };

  const t = {};
  const get = n => (t[n] = t[n] || { sf: 0, sa: 0, w: 0, games: 0 });
  for (const m of enriched) {
    const H = get(m.home), A = get(m.away);
    H.sf += m.w * (m.hVal / homeAdv); H.sa += m.w * m.aVal; H.w += m.w; H.games++;
    A.sf += m.w * m.aVal; A.sa += m.w * (m.hVal / homeAdv); A.w += m.w; A.games++;
  }
  for (const [team, s] of Object.entries(t)) {
    const k = s.w / (s.w + SHRINK_K);
    ratings[league + '|' + team] = {
      team, league,
      attack: k * ((s.sf / s.w) / leagueAvg) + (1 - k) * PRIOR_ATT,
      defence: k * ((s.sa / s.w) / leagueAvg) + (1 - k) * PRIOR_DEF,
      matches: s.games,
    };
  }
}

return [{ json: {
  ratings, leagueMeta, config, leagues,
  total_matches: matches.length,
  fetch_errors: fetchErrors,
  teams_rated: Object.keys(ratings).length,
}}];

// A modell mellé most az odds kell. Ligankent egy kereses.
const m = $json;
return (m.leagues || []).map(lg => ({ json: {
  ...lg,
  _model: { ratings: m.ratings, leagueMeta: m.leagueMeta, config: m.config,
            total_matches: m.total_matches, fetch_errors: m.fetch_errors,
            teams_rated: m.teams_rated },
}}));

// Tippek eloallitasa: Poisson + Dixon-Coles, majd osszevetes a piaccal.

const MAX_GOALS = 10;
const RHO = -0.13;

function poissonPmf(k, lambda) {
  let logF = 0;
  for (let i = 2; i <= k; i++) logF += Math.log(i);
  return Math.exp(-lambda + k * Math.log(lambda) - logF);
}
function tau(hg, ag, lh, la, rho) {
  if (hg === 0 && ag === 0) return 1 - lh * la * rho;
  if (hg === 0 && ag === 1) return 1 + lh * rho;
  if (hg === 1 && ag === 0) return 1 + la * rho;
  if (hg === 1 && ag === 1) return 1 - rho;
  return 1;
}
function predict(hr, ar, leagueAvg, homeAdv) {
  const lh = hr.attack * ar.defence * leagueAvg * homeAdv;
  const la = ar.attack * hr.defence * leagueAvg;
  const grid = []; let total = 0;
  for (let h = 0; h <= MAX_GOALS; h++) {
    grid[h] = [];
    for (let a = 0; a <= MAX_GOALS; a++) {
      const p = poissonPmf(h, lh) * poissonPmf(a, la) * tau(h, a, lh, la, RHO);
      grid[h][a] = Math.max(0, p); total += grid[h][a];
    }
  }
  let home = 0, draw = 0, away = 0, over25 = 0, btts = 0;
  for (let h = 0; h <= MAX_GOALS; h++) for (let a = 0; a <= MAX_GOALS; a++) {
    const p = grid[h][a] / total;
    if (h > a) home += p; else if (h === a) draw += p; else away += p;
    if (h + a > 2.5) over25 += p;
    if (h > 0 && a > 0) btts += p;
  }
  return { lh, la, probs: [home, draw, away], over25, btts };
}

// Csapatnev-parositas. A ket forras maskepp irja a neveket.
const ALIAS = {
  'manchester united': 'Man United', 'manchester city': 'Man City',
  'newcastle united': 'Newcastle', 'tottenham hotspur': 'Tottenham',
  'wolverhampton wanderers': 'Wolves', 'nottingham forest': "Nott'm Forest",
  'brighton and hove albion': 'Brighton', 'brighton & hove albion': 'Brighton',
  'west ham united': 'West Ham', 'leeds united': 'Leeds',
  'leicester city': 'Leicester', 'ipswich town': 'Ipswich',
  'sheffield united': 'Sheffield United', 'luton town': 'Luton',
  'afc bournemouth': 'Bournemouth', 'crystal palace': 'Crystal Palace',
  'atletico madrid': 'Ath Madrid', 'athletic bilbao': 'Ath Bilbao',
  'real sociedad': 'Sociedad', 'real betis': 'Betis',
  'celta vigo': 'Celta', 'rayo vallecano': 'Vallecano',
  'deportivo alaves': 'Alaves', 'real valladolid': 'Valladolid',
  'racing santander': 'Santander', 'real madrid': 'Real Madrid',
  'fc barcelona': 'Barcelona', 'barcelona': 'Barcelona',
  'bayern munich': 'Bayern Munich', 'bayern münchen': 'Bayern Munich',
  'borussia dortmund': 'Dortmund', 'borussia monchengladbach': "M'gladbach",
  'bayer leverkusen': 'Leverkusen', 'eintracht frankfurt': 'Ein Frankfurt',
  'vfb stuttgart': 'Stuttgart', 'vfl wolfsburg': 'Wolfsburg',
  'werder bremen': 'Werder Bremen', 'fc koln': 'FC Koln', '1. fc koln': 'FC Koln',
  'rb leipzig': 'RB Leipzig', 'sc freiburg': 'Freiburg', 'fc augsburg': 'Augsburg',
  'mainz 05': 'Mainz', 'fsv mainz 05': 'Mainz', 'tsg hoffenheim': 'Hoffenheim',
  'inter milan': 'Inter', 'ac milan': 'Milan', 'as roma': 'Roma',
  'juventus': 'Juventus', 'ss lazio': 'Lazio', 'ssc napoli': 'Napoli',
  'atalanta bc': 'Atalanta', 'acf fiorentina': 'Fiorentina',
  'hellas verona': 'Verona', 'us lecce': 'Lecce', 'torino fc': 'Torino',
  'paris saint germain': 'Paris SG', 'paris saint-germain': 'Paris SG',
  'olympique marseille': 'Marseille', 'olympique lyonnais': 'Lyon',
  'as monaco': 'Monaco', 'lille osc': 'Lille', 'stade rennais': 'Rennes',
  'ogc nice': 'Nice', 'rc lens': 'Lens', 'fc nantes': 'Nantes',
};
const norm = s => String(s).toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim();

function findTeam(ratings, league, apiName) {
  const direct = ratings[league + '|' + apiName];
  if (direct) return direct;
  const n = norm(apiName);
  const aliased = ALIAS[n];
  if (aliased && ratings[league + '|' + aliased]) return ratings[league + '|' + aliased];
  // laza egyezes: normalizalt nev, vagy az egyik tartalmazza a masikat
  const keys = Object.keys(ratings).filter(k => k.startsWith(league + '|'));
  for (const k of keys) {
    const t = k.slice(league.length + 1);
    const nt = norm(t);
    if (nt === n) return ratings[k];
  }
  for (const k of keys) {
    const t = k.slice(league.length + 1);
    const nt = norm(t);
    if (nt.length >= 4 && (n.includes(nt) || nt.includes(n))) return ratings[k];
  }
  return null;
}

// --- feldolgozas ---
const tips = [];
const unmatched = [];
const tooThin = [];
const oddsErrors = [];
let model = null, eventsSeen = 0;

for (const item of $input.all()) {
  const j = item.json;
  if (!model && j._model) model = j._model;
  const mdl = j._model || model;
  if (!mdl) continue;
  const cfg = mdl.config || {};
  const league = j.code;
  const leagueName = j.name;

  const status = j.statusCode;
  const body = j.body !== undefined ? j.body : j;
  if (status && status !== 200) {
    oddsErrors.push(`${leagueName}: HTTP ${status}`);
    continue;
  }
  if (!Array.isArray(body)) continue;

  const meta = (mdl.leagueMeta || {})[league];
  if (!meta) continue;

  for (const ev of body) {
    eventsSeen++;
    if (!ev.bookmakers || ev.bookmakers.length < 3) continue;
    const kickoff = new Date(ev.commence_time);
    const hoursAhead = (kickoff - new Date()) / 3600000;
    if (hoursAhead < 0 || hoursAhead > (cfg.maxHoursAhead || 72)) continue;

    const hr = findTeam(mdl.ratings, league, ev.home_team);
    const ar = findTeam(mdl.ratings, league, ev.away_team);
    if (!hr || !ar) {
      if (!hr) unmatched.push(`${leagueName}: ${ev.home_team}`);
      if (!ar) unmatched.push(`${leagueName}: ${ev.away_team}`);
      continue;
    }
    // Keves meccsu csapat (pl. frissen feljutott ujonc a szezon elejen):
    // a rating megbizhatatlan. Kihagyjuk, DE jelezzuk — kulonben a szezon
    // elejen meccsek tucatjai tunnenek el csendben.
    if (hr.matches < 8 || ar.matches < 8) {
      const thin = [];
      if (hr.matches < 8) thin.push(`${hr.team} (${hr.matches})`);
      if (ar.matches < 8) thin.push(`${ar.team} (${ar.matches})`);
      tooThin.push(`${leagueName}: ${ev.home_team} vs ${ev.away_team} — ${thin.join(', ')}`);
      continue;
    }

    const pr = predict(hr, ar, meta.leagueAvg, meta.homeAdv);

    // odds osszegyujtese kimenetelenkent
    const byOut = { 0: [], 1: [], 2: [] };
    for (const bk of ev.bookmakers) {
      const mk = (bk.markets || []).find(x => x.key === 'h2h');
      if (!mk || !mk.outcomes) continue;
      for (const oc of mk.outcomes) {
        const price = Number(oc.price);
        if (!Number.isFinite(price) || price <= 1) continue;
        let idx = null;
        if (oc.name === ev.home_team) idx = 0;
        else if (oc.name === ev.away_team) idx = 2;
        else if (String(oc.name).toLowerCase() === 'draw') idx = 1;
        if (idx === null) continue;
        byOut[idx].push({ book: bk.title || bk.key, key: bk.key, price });
      }
    }
    if (byOut[0].length < 3 || byOut[1].length < 3 || byOut[2].length < 3) continue;

    // piaci (de-vigelt) valoszinusegek a legjobb arakbol
    const bestOf = i => byOut[i].reduce((a, b) => (b.price > a.price ? b : a));
    const best = [bestOf(0), bestOf(1), bestOf(2)];
    const ipSum = best.reduce((a, b) => a + 1 / b.price, 0);
    const marketProbs = best.map(b => (1 / b.price) / ipSum);
    const marginPct = (ipSum - 1) * 100;

    // a modell tippje: a legvaloszinubb kimenetel, DE csak minOdds felett
    const labels = ['1 (hazai)', 'X (dontetlen)', '2 (vendeg)'];
    const names = [ev.home_team, 'Dontetlen', ev.away_team];
    let pick = -1, pickP = 0;
    for (let k = 0; k < 3; k++) {
      if (best[k].price < (cfg.minOdds || 1.3)) continue;
      if (best[k].price > (cfg.maxOdds || 8)) continue;
      if (pr.probs[k] > pickP) { pickP = pr.probs[k]; pick = k; }
    }
    if (pick < 0) continue;

    const avgPrice = byOut[pick].reduce((a, b) => a + b.price, 0) / byOut[pick].length;
    const mine = byOut[pick].find(b => b.key === (cfg.myBook || 'bet365'));
    const gapVsAvg = (best[pick].price / avgPrice - 1) * 100;
    const gapVsMine = mine ? (best[pick].price / mine.price - 1) * 100 : null;

    // BIZALOM: a modell es a piac egyetertesebol.
    // Merve: ahol a modell erosen ELTER a piactol, ott jellemzoen a modell teved
    // (a backteszt szerint a legnagyobb elteresek a legnagyobb hibak).
    const diff = pr.probs[pick] - marketProbs[pick];
    let confidence, confNote;
    if (Math.abs(diff) <= 0.03) { confidence = 'MAGAS'; confNote = 'a modell es a piac egyetert'; }
    else if (diff < -0.03)      { confidence = 'KOZEPES'; confNote = 'a piac ennel jobbnak latja'; }
    else if (diff <= 0.08)      { confidence = 'KOZEPES'; confNote = 'a modell kicsit tobbet lat'; }
    else                        { confidence = 'ALACSONY'; confNote = 'a modell sokkal tobbet lat — ez jellemzoen modellhiba, nem ertek'; }

    tips.push({
      league: leagueName, match_name: `${ev.home_team} vs ${ev.away_team}`,
      kickoff: ev.commence_time, hours_ahead: Math.round(hoursAhead * 10) / 10,
      pick_label: labels[pick], pick_name: names[pick],
      model_prob: Math.round(pr.probs[pick] * 1000) / 10,
      market_prob: Math.round(marketProbs[pick] * 1000) / 10,
      all_model: pr.probs.map(p => Math.round(p * 1000) / 10),
      all_market: marketProbs.map(p => Math.round(p * 1000) / 10),
      best_odds: Math.round(best[pick].price * 100) / 100,
      best_book: best[pick].book,
      avg_odds: Math.round(avgPrice * 100) / 100,
      my_odds: mine ? Math.round(mine.price * 100) / 100 : null,
      gap_pct: Math.round((gapVsMine === null ? gapVsAvg : gapVsMine) * 10) / 10,
      gap_is_vs_mine: gapVsMine !== null,
      margin_pct: Math.round(marginPct * 10) / 10,
      confidence, conf_note: confNote,
      exp_goals: `${(pr.lh).toFixed(1)}-${(pr.la).toFixed(1)}`,
      over25: Math.round(pr.over25 * 1000) / 10,
      btts: Math.round(pr.btts * 1000) / 10,
      book_count: byOut[pick].length,
    });
  }
}

const summary = {
  _summary: true,
  events_seen: eventsSeen,
  tips_found: tips.length,
  unmatched: [...new Set(unmatched)],
  too_thin: [...new Set(tooThin)],
  odds_errors: oddsErrors,
  model_matches: model ? model.total_matches : 0,
  model_teams: model ? model.teams_rated : 0,
  fetch_errors: model ? model.fetch_errors : [],
  config: model ? model.config : {},
};

if (!tips.length) return [{ json: summary }];
return [...tips.map(t => ({ json: t })), { json: summary }];

// Telegram uzenet osszeallitasa. Egy uzenet, meccsenkent egy blokk.

const all = $input.all().map(i => i.json);
const sum = all.find(x => x._summary) || {};
const tips = all.filter(x => !x._summary);
const cfg = sum.config || {};
const maxTips = cfg.maxTips || 15;

const fmt = iso => {
  try {
    return new Date(iso).toLocaleString('hu-HU', { timeZone: 'Europe/Budapest',
      month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' });
  } catch (e) { return iso; }
};

// rendezes: eloszor a magas bizalmuak, azon belul a kozelebbi meccsek
const rank = { 'MAGAS': 0, 'KOZEPES': 1, 'ALACSONY': 2 };
tips.sort((a, b) => (rank[a.confidence] - rank[b.confidence]) || (a.hours_ahead - b.hours_ahead));
const shown = tips.slice(0, maxTips);

let msg;
if (!shown.length) {
  msg = `⚽ Nincs tipp\n\n${sum.events_seen || 0} meccs atnezve, egyik sem felelt meg a szuronek (min ${cfg.minOdds || 1.3} odds, ${cfg.maxHoursAhead || 72} oran belul).`;
} else {
  const icon = { 'MAGAS': '🟢', 'KOZEPES': '🟡', 'ALACSONY': '🔴' };
  const blocks = shown.map(t => {
    const priceLine = t.gap_pct >= (cfg.minGapPct || 2)
      ? `💰 ${t.best_book}: ${t.best_odds}  (${t.gap_is_vs_mine ? 'nalad: ' + t.my_odds : 'atlag: ' + t.avg_odds})  +${t.gap_pct}%`
      : `   ${t.best_book}: ${t.best_odds}  (atlag ${t.avg_odds})`;
    const warn = t.margin_pct > 8 ? `\n   ⚠️ magas piaci margo (${t.margin_pct}%)` : '';
    return `${icon[t.confidence]} ${t.match_name}\n`
      + `   ${fmt(t.kickoff)} · ${t.league}\n`
      + `   TIPP: ${t.pick_label}\n`
      + `   modell ${t.model_prob}% · piac ${t.market_prob}%\n`
      + `   varhato eredmeny ${t.exp_goals} · O2.5 ${t.over25}% · BTTS ${t.btts}%\n`
      + `${priceLine}\n`
      + `   ${t.conf_note}${warn}`;
  });
  const hi = shown.filter(t => t.confidence === 'MAGAS').length;
  const lo = shown.filter(t => t.confidence === 'ALACSONY').length;
  msg = `⚽ TIPPEK — ${shown.length} meccs\n`
    + `🟢 ${hi} megbizhato · 🔴 ${lo} ovatosan\n\n`
    + blocks.join('\n\n')
    + `\n\n──────────\n`
    + `Modell: ${sum.model_matches} meccs, ${sum.model_teams} csapat\n`
    + `A modell 49.6%-ban talal (veletlen: 33%), de a fogadoiroda 54.6% — es a margo miatt\n`
    + `a fogadas hosszu tavon vesztesegеs. Dontestamogatas, nem garancia.`;
}

const probs = [];
if ((sum.too_thin || []).length) probs.push(`ℹ️ Kihagyva keves adat miatt (${sum.too_thin.length}):\n${sum.too_thin.slice(0, 5).join('\n')}\nA szezon elejen ez normalis — az ujoncoknak meg nincs eleg meccsuk.`);
if ((sum.unmatched || []).length) probs.push(`⚠️ Parositatlan csapatok (${sum.unmatched.length}):\n${sum.unmatched.slice(0, 6).join('\n')}`);
if ((sum.odds_errors || []).length) probs.push(`⚠️ Odds hibak:\n${sum.odds_errors.slice(0, 3).join('\n')}`);
if ((sum.fetch_errors || []).length) probs.push(`⚠️ Adatletoltes:\n${sum.fetch_errors.slice(0, 3).join('\n')}`);
if (probs.length) msg += `\n\n${probs.join('\n\n')}`;

return [{ json: { message: msg, tip_count: shown.length,
  high_conf: shown.filter(t => t.confidence === 'MAGAS').length,
  events_seen: sum.events_seen || 0,
  unmatched_count: (sum.unmatched || []).length,
  too_thin_count: (sum.too_thin || []).length } }];
